using DataVo.Core;
using DataVo.Core.StorageEngine.Config;
using DataVo.VectorData;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.VectorData;

namespace DataVo.AotSmoke;

/// <summary>A typed vector record: auto-generated Guid key, indexed data, a dated column and an HNSW vector.</summary>
public sealed class SmokeArticle
{
    [VectorStoreKey]
    public Guid Id { get; set; }

    [VectorStoreData(IsIndexed = true)]
    public string Topic { get; set; } = "";

    [VectorStoreData]
    public string Path { get; set; } = "";

    [VectorStoreData]
    public DateTime Published { get; set; }

    [VectorStoreData]
    public DateOnly Day { get; set; }

    [VectorStoreData]
    public int Rank { get; set; }

    [VectorStoreVector(SmokeEmbeddings.Dimensions, DistanceFunction = DistanceFunction.CosineSimilarity)]
    public ReadOnlyMemory<float> Embedding { get; set; }
}

/// <summary>A Guid key the application assigns: Native AOT must still see <c>IsAutoGenerated = false</c>.</summary>
public sealed class SmokeManualKey
{
    [VectorStoreKey(IsAutoGenerated = false)]
    public Guid Id { get; set; }

    [VectorStoreVector(2)]
    public float[]? Vector { get; set; }
}

/// <summary>A deterministic embedding generator: counts of the letters a-d.</summary>
public sealed class SmokeEmbeddings : IEmbeddingGenerator<string, Embedding<float>>
{
    public const int Dimensions = 4;

    public Task<GeneratedEmbeddings<Embedding<float>>> GenerateAsync(
        IEnumerable<string> values,
        EmbeddingGenerationOptions? options = null,
        CancellationToken cancellationToken = default)
    {
        var result = new GeneratedEmbeddings<Embedding<float>>();
        foreach (string value in values)
        {
            var vector = new float[Dimensions];
            foreach (char c in value)
            {
                if (c is >= 'a' and <= 'd')
                {
                    vector[c - 'a'] += 1;
                }
            }

            vector[^1] += 0.01f;
            result.Add(new Embedding<float>(vector));
        }

        return Task.FromResult(result);
    }

    public object? GetService(Type serviceType, object? serviceKey = null) => null;

    public void Dispose()
    {
    }
}

/// <summary>
/// End-to-end <c>DataVo.VectorData</c> scenario under Native AOT: typed and dynamic collections, Guid key generation
/// (and the explicit <c>IsAutoGenerated = false</c> flag), filters evaluated without compiling expressions
/// (constructors, arithmetic, escaped LIKE), text search through an embedding generator, and GetService.
/// </summary>
internal static class VectorDataSmoke
{
    public static void Run() => RunAsync().GetAwaiter().GetResult();

    private static async Task RunAsync()
    {
        Console.WriteLine("[6] DataVo.VectorData");
        var generator = new SmokeEmbeddings();
        using var store = new DataVoVectorStore(
            new DataVoConfig { StorageMode = StorageMode.InMemory },
            new DataVoVectorStoreOptions { EmbeddingGenerator = generator });

        var articles = new DataVoVectorStoreCollection<Guid, SmokeArticle>(store, "articles");
        await articles.EnsureCollectionExistsAsync();
        string[] texts = ["aaab", "bbbc", "cccd", "ddda"];
        GeneratedEmbeddings<Embedding<float>> vectors = await generator.GenerateAsync(texts);
        var records = new List<SmokeArticle>();
        for (int i = 0; i < texts.Length; i++)
        {
            records.Add(new SmokeArticle
            {
                Topic = i % 2 == 0 ? "db" : "ai",
                Path = i == 1 ? "50%_off.md" : $"doc{i}.md",
                Published = new DateTime(2026, 1, 1 + i, 0, 0, 0, DateTimeKind.Utc),
                Day = new DateOnly(2026, 1, 1 + i),
                Rank = i + 1,
                Embedding = vectors[i].Vector,
            });
        }

        await articles.UpsertAsync(records);
        Require(records.All(record => record.Id != Guid.Empty), "Guid keys are generated on upsert");

        SmokeArticle? first = await articles.GetAsync(records[0].Id);
        Require(first is { Topic: "db", Rank: 1 } && first.Day == new DateOnly(2026, 1, 1), "get by key round-trips the record");

        int min = 1;
        List<SmokeArticle> filtered = await ToListAsync(articles.GetAsync(
            article => article.Published >= new DateTime(2026, 1, 2, 0, 0, 0, DateTimeKind.Utc) && article.Rank > min + 1,
            top: 10));
        Require(filtered.Count == 2, $"constructor + arithmetic filter (got {filtered.Count})");

        List<SmokeArticle> escaped = await ToListAsync(articles.GetAsync(article => article.Path.StartsWith("50%_"), top: 10));
        Require(escaped.Count == 1 && escaped[0].Rank == 2, "LIKE wildcards in a StartsWith value are escaped");

        List<VectorSearchResult<SmokeArticle>> byVector = await ToListAsync(articles.SearchAsync(vectors[2].Vector, top: 1));
        Require(byVector.Count == 1 && byVector[0].Record.Rank == 3, "vector search ranks the nearest record first");

        List<VectorSearchResult<SmokeArticle>> byText = await ToListAsync(articles.SearchAsync("ddda", top: 1,
            new VectorSearchOptions<SmokeArticle> { Filter = article => article.Topic == "ai" }));
        Require(byText.Count == 1 && byText[0].Record.Rank == 4, "text search embeds the query with the store generator");

        Require(ReferenceEquals(articles.GetService(typeof(DataVoContext)), store.Context), "GetService exposes the DataVoContext");
        Require(ReferenceEquals(articles.GetService(typeof(IEmbeddingGenerator)), generator), "GetService exposes the embedding generator");

        var manual = new DataVoVectorStoreCollection<Guid, SmokeManualKey>(store, "manual");
        await manual.EnsureCollectionExistsAsync();
        var zero = new SmokeManualKey { Id = Guid.Empty, Vector = [1, 0] };
        await manual.UpsertAsync(zero);
        Require(zero.Id == Guid.Empty && await manual.GetAsync(Guid.Empty) is not null, "IsAutoGenerated = false keeps the assigned Guid under AOT");

        var definition = new VectorStoreCollectionDefinition
        {
            Properties =
            [
                new VectorStoreKeyProperty("Id", typeof(Guid)),
                new VectorStoreDataProperty("Label", typeof(string)),
                new VectorStoreVectorProperty("Vector", typeof(ReadOnlyMemory<float>), 2),
            ],
        };
        VectorStoreCollection<object, Dictionary<string, object?>> points = store.GetDynamicCollection("points", definition);
        await points.EnsureCollectionExistsAsync();
        var point = new Dictionary<string, object?> { ["Id"] = null, ["Label"] = "origin", ["Vector"] = new ReadOnlyMemory<float>([0, 1]) };
        await points.UpsertAsync(point);
        Require(point["Id"] is Guid id && id != Guid.Empty, "dynamic upsert generates a null Guid key");
        List<VectorSearchResult<Dictionary<string, object?>>> nearest = await ToListAsync(points.SearchAsync(new float[] { 0, 1 }, top: 1));
        Require(nearest.Count == 1 && (string?)nearest[0].Record["Label"] == "origin", "dynamic collection search");
    }

    private static async Task<List<T>> ToListAsync<T>(IAsyncEnumerable<T> source)
    {
        var list = new List<T>();
        await foreach (T item in source)
        {
            list.Add(item);
        }

        return list;
    }

    private static void Require(bool condition, string message)
    {
        if (!condition)
        {
            Console.Error.WriteLine($"FAIL: {message}");
            Environment.Exit(1);
        }

        Console.WriteLine($"  ok: {message}");
    }
}
